const source = $json;
const file = $binary?.file || {};
const fileName = file.fileName || '';

// ── 1. Normalize text field (PDF outputs 'text', Markdown outputs 'extracted_text') ──
const extractedText = source.extracted_text || source.text || '';

// ── 2. Parse metadata from the text content ──
function parseTextMeta(text) {
  if (!text) return {};
  const meta = {};

  const docIdMatch = text.match(/Document ID\s+([^\n]+)/i);
  if (docIdMatch) meta.doc_id = docIdMatch[1].trim();

  const tenantMatch = text.match(/Tenant\s+([^\n]+)/i);
  if (tenantMatch) meta.tenant_id = tenantMatch[1].trim();

  const categoryMatch = text.match(/Category\s+([^\n]+)/i);
  if (categoryMatch) meta.category = categoryMatch[1].trim();

  const versionMatch = text.match(/Version\s+([^\n]+)/i);
  if (versionMatch) meta.version = versionMatch[1].trim();

  const updatedMatch = text.match(/Last Updated\s+([^\n]+)/i);
  if (updatedMatch) meta.last_updated = updatedMatch[1].trim();

  const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  if (lines.length > 0) meta.title = lines[0];

  return meta;
}

const textMeta = parseTextMeta(extractedText);

// ── 3. Parse filename as fallback ──
const baseName = fileName.replace(/\.[^.]+$/, '');
const nameParts = baseName.split('_');
const filenameTenantId = nameParts[0] || '';
const filenameDocId = nameParts[1] || '';
const filenameTitle = nameParts.slice(2).join('_')
  .replace(/[-_]+/g, ' ')
  .replace(/\b\w/g, c => c.toUpperCase());

// ── 4. Resolve file type robustly ──
const rawExtension = file.fileExtension || '';
const fromFileName = (file.fileName || '').split('.').pop() || '';
const fromMimeType = (file.mimeType || '').includes('pdf') ? 'pdf' 
                   : (file.mimeType || '').includes('markdown') ? 'md'
                   : (file.mimeType || '').includes('text') ? 'txt'
                   : '';

const fileType = (source.file_type || rawExtension || fromFileName || fromMimeType).toLowerCase();

// ── 5. Resolve IDs and metadata ──
const tenant_id = textMeta.tenant_id || source.tenant_id || filenameTenantId || '';
const doc_id = textMeta.doc_id || source.doc_id || filenameDocId || '';
const title = textMeta.title || source.title || filenameTitle || 'Untitled Document';
const category = textMeta.category || source.category || 'general';
const version = textMeta.version || source.version || '1.0';
const last_updated = textMeta.last_updated || source.last_updated || new Date().toISOString().slice(0, 10);

// ── 6. Build clean doc_id if still missing ──
const finalDocId = doc_id || `doc-${baseName.replace(/\s+/g, '-').toLowerCase()}-${Date.now().toString(36).slice(-4)}`;

return [{
