// Header-aware chunking per chunking-strategy.md
// 1. Split on ## / ### headings
// 2. If section > 500 tokens (~2000 chars), sub-split into ~400-token chunks with 50-token overlap
// 3. Never split mid-sentence
// 4. Prepend title + section_heading to embedded text for better retrieval

const doc = $json;
const text = doc.extracted_text || '';
const headingRegex = /^(#{2,3})\s+(.*)$/gm;

let sections = [];
let lastIndex = 0;
let lastHeading = doc.title;
let match;
const matches = [...text.matchAll(headingRegex)];

if (matches.length === 0) {
  sections.push({ heading: doc.title, body: text });
} else {
  matches.forEach((m, i) => {
    const start = m.index;
    if (i === 0 && start > 0) {
      sections.push({ heading: doc.title, body: text.slice(0, start).trim() });
    }
    const end = i + 1 < matches.length ? matches[i + 1].index : text.length;
    sections.push({ heading: m[2].trim(), body: text.slice(start, end).replace(headingRegex, '').trim() });
  });
}

const CHARS_PER_CHUNK = 1600; // ~400 tokens
const OVERLAP_CHARS = 200;    // ~50 tokens

function splitBySentence(body, maxChars, overlap) {
  const sentences = body.match(/[^.!?]+[.!?]+(\s|$)/g) || [body];
  const chunks = [];
  let current = '';
  for (const s of sentences) {
    if ((current + s).length > maxChars && current.length > 0) {
      chunks.push(current.trim());
      const overlapText = current.slice(-overlap);
      current = overlapText + s;
    } else {
      current += s;
    }
  }
  if (current.trim()) chunks.push(current.trim());
  return chunks;
}

const chunks = [];
let chunkIndex = 0;
for (const section of sections) {
  if (!section.body) continue;
  const bodyChunks = section.body.length <= 2000
    ? [section.body]
    : splitBySentence(section.body, CHARS_PER_CHUNK, OVERLAP_CHARS);

  for (const body of bodyChunks) {
    chunkIndex += 1;
    chunks.push({
      chunk_id: `${doc.doc_id}-c${chunkIndex}`,
      doc_id: doc.doc_id,
      tenant_id: doc.tenant_id,
      industry_pack: doc.industry_pack,
      title: doc.title,
      section_heading: section.heading,
      category: doc.category,
      version: doc.version,
      last_updated: doc.last_updated,
      chunk_index: chunkIndex,
      embed_text: `${doc.title} — ${section.heading}\n${body}`,
      text: body
    });
  }
}

return chunks.map(c => ({ json: c }));

