const ctx = $('[ESCALATION] - Prepare Additional Information Request').item.json;

const analysis = ctx.update_analysis || {};
const intake = ctx.intake_context || {};

const missing = Array.isArray(analysis.still_missing_information)
  ? analysis.still_missing_information
  : [];

const provided = Array.isArray(analysis.provided_information)
  ? analysis.provided_information
  : [];

const customerMessage =
  intake.customer_message ||
  ctx.text ||
  '';

const prompt = `
You are an empathetic customer support escalation assistant.

The customer is already in an escalation workflow.

They have just provided additional information. The case is NOT yet ready for human investigation because some useful information is still missing.

Customer's latest message:
${customerMessage}

Information newly provided:
${JSON.stringify(provided)}

Information still missing:
${JSON.stringify(missing)}

Rules:

- Acknowledge what the customer just provided.
- Thank them for providing the information.
- Do not ask for information they already supplied.
- Ask only for the remaining information that is genuinely useful.
- Keep the request concise and practical.
- Never request passwords, CVVs, full card numbers, one-time authentication codes, or other sensitive credentials.
- If a screenshot would help, ask for a redacted screenshot and explicitly tell the customer to hide sensitive payment or authentication information.
- Do not claim the case is ready for a human agent.
- Do not claim a human agent has already reviewed the case.
- Do not invent policy, refund, account, or transaction details.
- Sound like a real, empathetic support representative.
- Avoid generic phrases such as "we value your patience."
- Make the response specific to the information the customer just provided.

Write ONLY the customer-facing response.
`;

return [{
  json: {
    ...ctx,
    follow_up_prompt: prompt
  }
}];

const generatedText = $json.text || '';

return [{
  json: {
    ...$json,

    response_text: generatedText,
    customer_response: generatedText
  }
}];

const ctx = $('[ESCALATION] - Prepare Human Handoff').item.json;

const caseUpdate = ctx.case_update || {};
const caseId = caseUpdate.case_id || null;

const response =
  "Thanks for providing those details. I’ve added them to your case, and it’s now ready for our support team to review. A human support agent will follow up with you.";

return [{
  json: {
    ...ctx,

    response_text: response,

    customer_response: response,

    case_id: caseId,

    escalation_state: 'READY_FOR_AGENT'
  }
}];

const d = $json;

return [{
  json: {
    ...d,

    decision: 'escalate',

    decision_reason: 'account_context_required',

    escalation_reasons: [
      'account_context_required'
    ],

    response_text:
      d.response_text ||
      "I need to verify information specific to your account before I can give you an accurate answer."
  }
}];

const ctx = $json;

const activeCase = ctx.active_escalation_case || {};

const prompt = `
You are a customer support conversation-state classifier.

An escalation case already exists for this customer conversation.

Your ONLY job is to determine whether the customer's NEW message is a follow-up to that existing escalation case or a new unrelated support request.

Existing escalation case:
Case ID: ${activeCase.case_id || '(unknown)'}
Escalation type: ${activeCase.escalation_type || '(unknown)'}
Status: ${activeCase.status || '(unknown)'}
Latest case message:
${activeCase.latest_customer_message || '(none)'}

Case context:
${activeCase.case_context || '{}'}

Customer's NEW message:
${ctx.text || '(none)'}

Classify the new message as exactly one of:

{
  "is_case_follow_up": true
}

OR

{
  "is_case_follow_up": false
}

Rules:

- true when the customer is providing requested information for the active case.
- true when the customer is clarifying, updating, or continuing the same issue.
- false when the customer starts a different support question or unrelated issue.
- Do not decide whether the case should be escalated.
- Do not create or close a case.
- Do not infer missing information.
- Return ONLY valid JSON.
`;

return [{
  json: {
    ...ctx,
    case_relevance_prompt: prompt
  }
}];

const result = $json.output || {};

const source =
  $('[ESCALATION] - Build Case Relevance Prompt').item.json || {};

const activeCase =
  source.active_escalation_case || null;

return [{
  json: {
    ...source,

    active_escalation_case: activeCase,

    active_escalation_exists:
      Boolean(
        source.active_escalation_exists &&
        activeCase?.case_id
      ),

    is_case_follow_up:
      result.is_case_follow_up === true
  }
}];
